#!/usr/bin/env node
/**
 * Per-publish compatibility manifest (Astryx-gap Phase 4, increment 1).
 *
 * Records the toolchain combinations ACTUALLY EXERCISED by the repo's gates —
 * resolved installed versions, never semver ranges — plus the declared peer
 * ranges of @digitaltableteur/react and how much of each range is actually
 * backed by evidence (exactly one resolved version). Embeds a summary of the
 * latest react publish preflight run when one exists.
 *
 * Writes public/ds-health/compatibility-manifest.json with the shared
 * provenance stamp. Regenerated by the react publish preflight so every
 * publish snapshots what was really tested.
 *
 * Usage: npm run audit:compatibility
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { arch, platform } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  assembleCompatibilityManifest,
  summarizePreflight,
} from "./compatibility-manifest-lib.mjs";
import {
  currentProvenance,
  runtimeStampFor,
} from "./evidence-stamp-lib.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const OUT = join(ROOT, "public/ds-health/compatibility-manifest.json");
const PREFLIGHT = join(
  ROOT,
  ".omx/state/design-system/react-publish-preflight/latest.json",
);
const GENERATOR_VERSION = 1;

/** Toolchain packages whose resolved versions the gates actually exercise. */
const TOOLCHAIN = [
  "react",
  "react-dom",
  "next",
  "typescript",
  "storybook",
  "vite",
  "vitest",
  "jsdom",
  "@playwright/test",
  "framer-motion",
  "react-markdown",
  "@phosphor-icons/react",
];

const WORKSPACE_PACKAGES = [
  "packages/react",
  "packages/cli",
  "packages/tokens",
  "packages/tokens-css",
  "packages/web-components",
];

function readJson(path) {
  return JSON.parse(readFileSync(path, "utf8"));
}

function installedVersion(name) {
  const manifestPath = join(ROOT, "node_modules", name, "package.json");
  if (!existsSync(manifestPath)) return null;
  try {
    return readJson(manifestPath).version ?? null;
  } catch {
    return null;
  }
}

const resolvedVersions = {};
for (const name of TOOLCHAIN) resolvedVersions[name] = installedVersion(name);

const workspacePackages = {};
for (const dir of WORKSPACE_PACKAGES) {
  const manifestPath = join(ROOT, dir, "package.json");
  if (!existsSync(manifestPath)) continue;
  const manifest = readJson(manifestPath);
  workspacePackages[manifest.name] = manifest.version;
}

const reactPackage = readJson(join(ROOT, "packages/react/package.json"));

let preflight = null;
if (existsSync(PREFLIGHT)) {
  try {
    preflight = summarizePreflight(readJson(PREFLIGHT));
  } catch {
    preflight = null;
  }
}

const substance = assembleCompatibilityManifest({
  workspacePackages,
  resolvedVersions,
  declaredPeerRanges: reactPackage.peerDependencies ?? {},
  runtime: { node: process.version, platform: platform(), arch: arch() },
  preflight,
});

const provenance = currentProvenance(ROOT, {
  name: "generate-compatibility-manifest",
  version: GENERATOR_VERSION,
});
const stamp = runtimeStampFor(OUT, substance, provenance);
const report = {
  generatedAt: stamp.generatedAt,
  ...substance,
  provenance: stamp.provenance,
};

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, `${JSON.stringify(report, null, 2)}\n`);

const exercisedCount = Object.values(resolvedVersions).filter(Boolean).length;
console.log(
  `✓ compatibility manifest written: ${exercisedCount}/${TOOLCHAIN.length} toolchain versions resolved, ` +
    `${Object.keys(workspacePackages).length} workspace packages, preflight ${preflight ? `embedded (${preflight.status})` : "absent"} → public/ds-health/compatibility-manifest.json`,
);
